import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class VarSerializationCompatibilityTest {

	@Test
	void serializationRetainsSemanticFieldsAndOmitsDerivedHashCache() {
		ObjectStreamClass descriptor = ObjectStreamClass.lookup(Var.class);
		assertNotNull(descriptor);
		assertAll(
				() -> assertEquals(-2002917920842280721L, descriptor.getSerialVersionUID()),
				() -> assertNull(descriptor.getField("cachedHashCode"), "a derived hash is not persistent query state"),
				() -> assertEquals(int.class, descriptor.getField("graphContextDepth").getType()),
				() -> assertEquals(boolean.class, descriptor.getField("apiInputOrigin").getType()));
	}

	@Test
	void nondefaultGraphDepthApiOriginAndEveryFlagCombinationSurviveCurrentRoundtrip() throws Exception {
		var value = SimpleValueFactory.getInstance().createIRI("urn:serialization:graph");
		for (int flags = 0; flags < 8; flags++) {
			Var source = Var.of("g", value, (flags & 1) != 0, (flags & 2) != 0, (flags & 4) != 0)
					.withApiInputOrigin();
			source.setGraphContextDepth(3);
			source.setVariableScopeChange(true);
			int expectedHash = source.hashCode();
			Var restored = roundtrip(source);
			assertNotSame(source, restored);
			assertAll(
					() -> assertEquals(source.getName(), restored.getName()),
					() -> assertEquals(value, restored.getValue()),
					() -> assertEquals(source.isAnonymous(), restored.isAnonymous()),
					() -> assertEquals(source.isConstant(), restored.isConstant()),
					() -> assertEquals(source.isBNode(), restored.isBNode()),
					() -> assertEquals(3, restored.getGraphContextDepth()),
					() -> assertTrue(restored.hasApiInputOrigin()),
					() -> assertTrue(restored.isVariableScopeChange()),
					() -> assertEquals(expectedHash, restored.hashCode()),
					() -> assertEquals(source, restored));
			Var cloned = restored.clone();
			assertEquals(3, cloned.getGraphContextDepth());
			assertTrue(cloned.hasApiInputOrigin());
			assertEquals(restored, cloned);
			assertEquals(restored.hashCode(), cloned.hashCode());
		}
	}

	private static Var roundtrip(Var source) throws Exception {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(source);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			return (Var) input.readObject();
		}
	}
}
